module pll_frecovery (  
    input clk,  
    input rst,  
    input signal_in,  
    output reg signal_out  
);  
    reg [3:0] phase_error;  
    reg [3:0] frequency;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            frequency <= 4'b0000;  
            signal_out <= 0;  
        end else begin  
            // Example frequency recovery logic  
            phase_error <= signal_in ? frequency + 1 : frequency - 1;  
            frequency <= phase_error;  
            signal_out <= (frequency > 4'b0010) ? 1 : 0;  
        end  
    end  
endmodule

