    output reg [3:0] freq // output frequency as 4-bit binary
);
    reg [15:0] count; // counter for edges

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            freq <= 0;
        end else if (sig) begin
            count <= count + 1;
        end else begin
            freq <= count[3:0]; // output lower 4 bits of count
            count <= 0;
        end
    end
endmodule

