module fractional_n_pll(
    input wire clk_ref,
    input wire reset,
    input wire [7:0] div_int, // Integer part of the division
    input wire [7:0] div_frac, // Fractional part (for delta-sigma modulation)
    output reg clk_out
);

reg [15:0] counter_int = 0;
reg [15:0] counter_frac = 0;
reg [15:0] frac_mod = 0;
parameter FRACTIONAL_MAX = 255; // Max value for fractional division

always @(posedge clk_ref or posedge reset) begin
    if (reset) begin
        counter_int <= 0;
        counter_frac <= 0;
        clk_out <= 0;
    end else begin
        counter_int <= counter_int + 1;
        if (counter_int >= div_int) begin
            counter_int <= 0;
            clk_out <= ~clk_out; // Toggle output clock
            // Handle fractional division
            frac_mod <= frac_mod + div_frac;
            if (frac_mod >= FRACTIONAL_MAX) begin
                frac_mod <= frac_mod - FRACTIONAL_MAX;
                clk_out <= ~clk_out; // Additional toggle for fractional part
            end
        end
    end
end

endmodule

