module chebyshev_filter (  
    input wire clk,  
    input wire reset,  
    input wire [15:0] x_in,  
    output reg [15:0] y_out  
);  
    parameter A0 = 16'h3F8C; // Coefficients for Chebyshev filter  
    parameter A1 = 16'h7F15;  
    parameter A2 = 16'h3F8C;  
    parameter B1 = 16'hFFFF;  
    parameter B2 = 16'hFFFF;  

    reg [15:0] x1, x2;  
    reg [15:0] y1, y2;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            x1 <= 16'h0000;  
            x2 <= 16'h0000;  
            y1 <= 16'h0000;  
            y2 <= 16'h0000;  
            y_out <= 16'h0000;  
        end else begin  
            // State update  
            y_out <= (A0 * x_in + A1 * x1 + A2 * x2 - B1 * y1 - B2 * y2) >> 16;  
            // Shift state  
            x2 <= x1;  
            x1 <= x_in;  
            y2 <= y1;  
            y1 <= y_out;  
        end  
    end  
endmodule

