module uart_tx (  
    input wire clk,  
    input wire rst,  
    input wire [7:0] data_in,  
    input wire send,  
    output reg tx,  
    output reg busy  
);  
    parameter IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;  
    reg [1:0] state, next_state;  
    reg [3:0] bit_index;  
    reg [9:0] shift_reg; // 1 start, 8 data, 1 stop  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            busy <= 0;  
            tx <= 1;  
        end else begin  
            state <= next_state;  
        end  
    end  

    always @(*) begin  
        case (state)  
            IDLE: begin  
                if (send) begin  
                    next_state = START;  
                    busy = 1;  
                end else begin  
                    next_state = IDLE;  
                    busy = 0;  
                end  
            end  
            START: begin  
                next_state = DATA;  
                shift_reg = {1'b1, data_in, 1'b0}; // Load data with start bit  
            end  
            DATA: begin  
                if (bit_index < 8) begin  
                    next_state = DATA;  
                    tx = shift_reg[bit_index];  
                    bit_index = bit_index + 1;  
                end else begin  
                    next_state = STOP;  
                end  
            end  
            STOP: begin  
                tx = 1;  
                busy = 0;  
                next_state = IDLE;  
            end  
            default: next_state = IDLE;  
        endcase  
    end  
endmodule

