module audio_buffer (
    input wire clk,
    input wire reset,
    input wire [15:0] sample_in,
    input wire compute_avg,
    output reg [15:0] avg_out
);
    reg [15:0] buffer [0:4]; // Buffer for 5 samples
    reg [2:0] count; // Counter for samples
    reg [31:0] sum; // Sum of samples for average calculation

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            sum <= 0;
            avg_out <= 0;
        end else if (count < 5) begin
            buffer[count] <= sample_in;
            sum <= sum + sample_in;
            count <= count + 1;
        end else if (compute_avg) begin
            avg_out <= sum / 5;
            sum <= 0; // Reset sum after computing average
            count <= 0; // Reset count to start filling buffer again
        end
    end
endmodule

