module i2c_controller(  
    input clk,  
    input rst,  
    input start,  
    input stop,  
    input [7:0] data_in,  
    output reg ack  
);  
    reg [2:0] state;  
    reg [7:0] data;  
    parameter IDLE = 3'b000, START = 3'b001, SEND = 3'b010, ACK = 3'b011, STOP = 3'b100;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            ack <= 0;  
        end else begin  
            case (state)  
                IDLE: if (start) state <= START;  
                START: begin  
                    data <= data_in;  
                    state <= SEND;  
                end  
                SEND: begin  
                    // Simulate data sending, here we just move to ACK state  
                    state <= ACK;  
                end  
                ACK: begin  
                    // Simulate receiving ACK  
                    ack <= 1;  
                    state <= STOP;  
                end  
                STOP: begin  
                    // End of transaction  
                    ack <= 0;  
                    state <= IDLE;  
                end  
                default: state <= IDLE;  
            endcase  
        end  
    end  
endmodule

