module pwm_generator(  
    input wire clk,  
    input wire rst,  
    input wire [6:0] duty_cycle,  
    output reg pwm_out  
);  
    reg [6:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            pwm_out <= 0;  
        end else begin  
            if (counter < 127) begin  
                counter <= counter + 1;  
            end else begin  
                counter <= 0;  
            end  

            if (counter < duty_cycle)  
                pwm_out <= 1;  
            else  
                pwm_out <= 0;  
        end  
    end  
endmodule

