module watchdog_timer(  
    input wire clk,  
    input wire enable,  
    input wire [3:0] timeout,  
    output reg timeout_event  
);  
    reg [3:0] counter;  
    always @(posedge clk) begin  
        if (enable) begin  
            counter <= 4'b0;  
            timeout_event <= 1'b1;  
        end else begin  
            if (counter < timeout) begin  
                counter <= counter + 1;  
            end else begin  
                timeout_event <= 1'b0;  
            end  
        end  
    end  
endmodule

