module rc_oscillator (  
    input clk,  
    input reset,  
    output reg out  
);  
    reg [23:0] counter;  
    parameter MAX_COUNT = 24'd1000000; // Adjust this value for desired frequency  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            out <= 0;  
        end else begin  
            if (counter < MAX_COUNT) begin  
                counter <= counter + 1;  
            end else begin  
                counter <= 0;  
                out <= ~out;  
            end  
        end  
    end  
endmodule

