module temp_shutdown_controller(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] temperature,  
    input wire [7:0] threshold,  
    output reg shutdown  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, MONITOR = 2'b01, SHUTDOWN = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            shutdown <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (temperature > threshold)  
                        state <= MONITOR;  
                end  
                MONITOR: begin  
                    if (temperature > threshold)  
                        state <= SHUTDOWN;  
                    else  
                        state <= IDLE;  
                end  
                SHUTDOWN: begin  
                    shutdown <= 1;  
                    if (temperature <= threshold)  
                        state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

