module dma_controller (
    input wire clk,
    input wire reset,
    input wire start_ch1,
    input wire start_ch2,
    output reg transfer_complete_ch1,
    output reg transfer_complete_ch2
);

reg [3:0] state; // 0: idle, 1: transfer ch1, 2: transfer ch2, 3: complete ch1, 4: complete ch2
parameter IDLE = 0, TRANSFER_CH1 = 1, TRANSFER_CH2 = 2, COMPLETE_CH1 = 3, COMPLETE_CH2 = 4;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= IDLE;
        transfer_complete_ch1 <= 0;
        transfer_complete_ch2 <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start_ch1) begin
                    state <= TRANSFER_CH1;
                end else if (start_ch2) begin
                    state <= TRANSFER_CH2;
                end
            end

            TRANSFER_CH1: begin
                // Simulate data transfer process
                state <= COMPLETE_CH1;
            end

            TRANSFER_CH2: begin
                // Simulate data transfer process
                state <= COMPLETE_CH2;
            end

            COMPLETE_CH1: begin
                transfer_complete_ch1 <= 1;
                state <= IDLE;
            end

            COMPLETE_CH2: begin
                transfer_complete_ch2 <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end
endmodule

