module watchdog_timer(
    input wire clk,
    input wire reset,
    output reg timeout
);
    parameter TIMEOUT_PERIOD = 8'd100; // Timeout period
    reg [7:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 8'd0;
            timeout <= 1'b0;
        end else begin
            if (counter < TIMEOUT_PERIOD) begin
                counter <= counter + 1;
            end else begin
                timeout <= 1'b1; // Set timeout signal
            end
        end
    end
endmodule

