module PID_Controller #(parameter WIDTH = 16) (  
    input clk,  
    input rst,  
    input [WIDTH-1:0] SP, // Setpoint  
    input [WIDTH-1:0] PV, // Process Variable  
    input [WIDTH-1:0] Kp, // Proportional Gain  
    input [WIDTH-1:0] Ki, // Integral Gain  
    input [WIDTH-1:0] Kd, // Derivative Gain  
    output reg [WIDTH-1:0] CV // Control Variable  
);  
    reg [WIDTH-1:0] integral;  
    reg [WIDTH-1:0] prev_error;  
    reg [WIDTH-1:0] error;  
    reg [WIDTH-1:0] derivative;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            integral <= 0;  
            prev_error <= 0;  
            CV <= 0;  
        end else begin  
            error <= SP - PV;  
            integral <= integral + error;  
            derivative <= error - prev_error;  
            CV <= (Kp * error) + (Ki * integral) + (Kd * derivative);  
            prev_error <= error;  
        end  
    end  
endmodule

