module d_flip_flop(  
    input wire clk,  
    input wire reset,  
    input wire preset,  
    input wire D,  
    output reg Q  
);  
    always @(posedge clk or posedge reset or posedge preset) begin  
        if (reset)  
            Q <= 1'b0;  
        else if (preset)  
            Q <= 1'b1;  
        else  
            Q <= D;  
    end  
endmodule

