module ofdm_modulator(  
    input clk,  
    input reset,  
    input start,  
    input [7:0] data_in,  
    output reg [7:0] symbol_out,  
    output reg valid  
);  

    parameter NUM_SUBCARRIERS = 4;  
    reg [1:0] state;  
    reg [1:0] subcarrier_index;  
    reg [7:0] symbols [0:NUM_SUBCARRIERS-1];  
    reg [3:0] bit_counter;  

    // State definitions  
    localparam IDLE = 2'b00;  
    localparam PROCESS = 2'b01;  
    localparam OUTPUT = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            subcarrier_index <= 0;  
            bit_counter <= 0;  
            valid <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        state <= PROCESS;  
                        bit_counter <= 0;  
                    end  
                    valid <= 0;  
                end  
                PROCESS: begin  
                    if (bit_counter < 8) begin  
                        symbols[subcarrier_index] <= (data_in[bit_counter] == 1'b1) ? 8'hFF : 8'h00; // BPSK modulation  
                        bit_counter <= bit_counter + 1;  
                    end else begin  
                        state <= OUTPUT;  
                        subcarrier_index <= 0;  
                        bit_counter <= 0;  
                    end  
                end  
                OUTPUT: begin  
                    if (subcarrier_index < NUM_SUBCARRIERS) begin  
                        symbol_out <= symbols[subcarrier_index];  
                        valid <= 1;  
                        subcarrier_index <= subcarrier_index + 1;  
                    end else begin  
                        state <= IDLE;  
                        valid <= 0;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

