module sipo_shift_register (  
    input clk,  
    input reset,  
    input serial_in,  
    output reg [3:0] parallel_out  
);  
    reg [3:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 4'b0000;  
        end else begin  
            shift_reg <= {shift_reg[2:0], serial_in};  
        end  
    end  

    always @(posedge clk) begin  
        parallel_out <= shift_reg;  
    end  
endmodule

module dynamic_range_compressor (
    input signed [15:0] in_signal,
    input [2:0] compression_ratio,
    output reg signed [15:0] out_signal
);
    always @(*) begin
        if (in_signal < 0) begin
            out_signal = -out_signal; // Handle negative values
        end else if (in_signal < 256) begin
            out_signal = in_signal; // No compression
        end else if (in_signal < 1024) begin
            out_signal = in_signal >>> 1; // 50% compression
        end else begin
            out_signal = in_signal >> (compression_ratio + 1); // Compression based on ratio
        end

        // Saturate to 16-bit signed range
        if (out_signal > 32767) 
            out_signal = 32767;
        else if (out_signal < -32768) 
            out_signal = -32768;
    end
endmodule

module uart_controller(
    input wire clk,
    input wire reset,
    input wire tx_en,
    input wire rx_en,
    input wire [7:0] data_in,
    output reg [7:0] data_out,
    output reg tx_busy,
    output reg rx_ready
);
    reg [3:0] baud_counter;
    reg [7:0] tx_data_reg;
    reg [7:0] rx_data_reg;
    reg tx_state;
    reg rx_state;

    // Baud rate logic, assuming clk is fast clock
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            baud_counter <= 0;
            tx_busy <= 0;
            rx_ready <= 0;
        end else begin
            baud_counter <= baud_counter + 1;

            // Simple baud rate control
            if (baud_counter == 10) begin
                baud_counter <= 0;
                if (tx_en && !tx_busy) begin
                    tx_busy <= 1;
                    tx_data_reg <= data_in;
                end

                if (tx_busy) begin
                    // Transmit logic (simplified)
                    data_out <= tx_data_reg; // In a real case, shift out bits
                    tx_busy <= 0; // End transmission for this example
                end

                // Receive logic (simplified)
                if (rx_en) begin
                    rx_ready <= 1;
                    rx_data_reg <= data_in; // Simulated received data
                end
                else begin
                    rx_ready <= 0;
                end
            end
        end
    end
endmodule

