module round_robin_arbiter (
    input wire clk,
    input wire rst,
    input wire [3:0] req, // Request signals
    output reg [3:0] grant // Grant signals
);
    reg [1:0] last_granted;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            grant <= 4'b0000;
            last_granted <= 2'b00; 
        end else begin
            // Clear grants
            grant <= 4'b0000;
            // Round robin grant logic
            case (last_granted)
                2'b00: begin
                    if (req[0]) begin
                        grant[0] <= 1'b1;
                        last_granted <= 2'b00;
                    end else if (req[1]) begin
                        grant[1] <= 1'b1;
                        last_granted <= 2'b01;
                    end else if (req[2]) begin
                        grant[2] <= 1'b1;
                        last_granted <= 2'b10;
                    end else if (req[3]) begin
                        grant[3] <= 1'b1;
                        last_granted <= 2'b11;
                    end
                end
                2'b01: begin
                    if (req[1]) begin
                        grant[1] <= 1'b1;
                        last_granted <= 2'b01;
                    end else if (req[2]) begin
                        grant[2] <= 1'b1;
                        last_granted <= 2'b10;
                    end else if (req[3]) begin
                        grant[3] <= 1'b1;
                        last_granted <= 2'b11;
                    end else if (req[0]) begin
                        grant[0] <= 1'b1;
                        last_granted <= 2'b00;
                    end
                end
                2'b10: begin
                    if (req[2]) begin
                        grant[2] <= 1'b1;
                        last_granted <= 2'b10;
                    end else if (req[3]) begin
                        grant[3] <= 1'b1;
                        last_granted <= 2'b11;
                    end else if (req[0]) begin
                        grant[0] <= 1'b1;
                        last_granted <= 2'b00;
                    end else if (req[1]) begin
                        grant[1] <= 1'b1;
                        last_granted <= 2'b01;
                    end
                end
                2'b11: begin
                    if (req[3]) begin
                        grant[3] <= 1'b1;
                        last_granted <= 2'b11;
                    end else if (req[0]) begin
                        grant[0] <= 1'b1;
                        last_granted <= 2'b00;
                    end else if (req[1]) begin
                        grant[1] <= 1'b1;
                        last_granted <= 2'b01;
                    end else if (req[2]) begin
                        grant[2] <= 1'b1;
                        last_granted <= 2'b10;
                    end
                end
            endcase
        end
    end
endmodule

