module dot_product (
    input [4:0] A,
    input [4:0] B,
    input valid,
    output reg [9:0] product,
    output reg ready
);
    always @(*) begin
        if (valid) begin
            product = A[0]*B[0] + A[1]*B[1] + A[2]*B[2] + A[3]*B[3] + A[4]*B[4];
            ready = 1;
        end else begin
            product = 10'b0;
            ready = 0;
        end
    end
endmodule

